BEGIN;
CREATE TABLE IF NOT EXISTS programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, tier text, track text, description text, sequence int, member_topic_gs int[] NOT NULL DEFAULT '{}', elective_gs int[] NOT NULL DEFAULT '{}', corequisite_gs int[] NOT NULL DEFAULT '{}', prerequisites text[] NOT NULL DEFAULT '{}', is_free boolean NOT NULL DEFAULT false, price_cents int, icon_url text, is_active boolean NOT NULL DEFAULT true, source text NOT NULL DEFAULT 'ccode', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, level text, track text, description text, sequence int, member_topic_gs int[] NOT NULL DEFAULT '{}', corequisite_gs int[] NOT NULL DEFAULT '{}', prerequisites text[] NOT NULL DEFAULT '{}', requirements jsonb NOT NULL DEFAULT '{}'::jsonb, icon_url text, is_active boolean NOT NULL DEFAULT true, source text NOT NULL DEFAULT 'ccode', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS program_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), program_id uuid NOT NULL REFERENCES programs(id) ON DELETE CASCADE, achievement_id uuid NOT NULL REFERENCES achievements(id), gs int NOT NULL, seq int, is_elective boolean NOT NULL DEFAULT false, UNIQUE(program_id,gs));
CREATE TABLE IF NOT EXISTS certificate_topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), certificate_id uuid NOT NULL REFERENCES certificates(id) ON DELETE CASCADE, achievement_id uuid NOT NULL REFERENCES achievements(id), gs int NOT NULL, seq int, is_required boolean NOT NULL DEFAULT true, UNIQUE(certificate_id,gs));
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, price_cents int NOT NULL, interval text, is_active boolean NOT NULL DEFAULT true, source text NOT NULL DEFAULT 'ccode');
SELECT p.id,a.id,g.gs,g.ord,(g.gs = ANY(p.elective_gs)) FROM programs p, unnest(p.member_topic_gs) WITH ORDINALITY g(gs,ord)
JOIN achievements a ON a.curriculum_version_id='51c1d5db-1d05-4d43-8853-5fa1503fb751' AND a.global_sequence=g.gs ON CONFLICT(program_id,gs) DO NOTHING;
SELECT p.id,a.id,g.gs,900+g.ord,true FROM programs p, unnest(p.elective_gs) WITH ORDINALITY g(gs,ord)
JOIN achievements a ON a.curriculum_version_id='51c1d5db-1d05-4d43-8853-5fa1503fb751' AND a.global_sequence=g.gs ON CONFLICT(program_id,gs) DO NOTHING;
SELECT c.id,a.id,g.gs,g.ord FROM certificates c, unnest(c.member_topic_gs) WITH ORDINALITY g(gs,ord)
JOIN achievements a ON a.curriculum_version_id='51c1d5db-1d05-4d43-8853-5fa1503fb751' AND a.global_sequence=g.gs ON CONFLICT(certificate_id,gs) DO NOTHING;
COMMIT;